1	using System.CommandLine;
2	using System.Text.RegularExpressions;
3	using Guardrails.Core.Graph;
4	using Guardrails.Core.Model;
5	using Guardrails.Core.State;
6	
7	namespace Guardrails.Cli.Commands;
8	
9	/// <summary>
10	/// <c>guardrails graph [folder] [--check] [--stdout] [--format mermaid]</c> — render the
11	/// plan's task/guardrail DAG as a Mermaid <c>flowchart TD</c> (SSOT §10). Default: write
12	/// <c>&lt;folder&gt;/diagram.md</c> (a provenance comment + a fenced <c>mermaid</c> block + a
13	/// one-line structure-only caption after the fence). <c>--check</c> writes nothing and reports
14	/// staleness via exit code (0 fresh, 2 stale/missing, 1 on a load/validate error). <c>--stdout</c>
15	/// prints the diagram instead of writing a file. Defaults to the current directory when the
16	/// folder is omitted.
17	/// </summary>
18	public static partial class GraphCommand
19	{
20	    private const string DiagramFileName = "diagram.md";
21	    private const string DiagramHtmlFileName = "diagram.html";
22	
23	    /// <summary>
24	    /// Exit code returned by <c>--check</c> when <c>diagram.md</c> is stale OR missing — the
25	    /// "regenerate" signal (SSOT §7: exit 2 = "the operation completed but an actionable
26	    /// condition was found"). Distinct from <see cref="ExitCodes.HarnessError"/> (1), which a
27	    /// genuine load/validate failure returns, so CI can tell "regenerate the diagram" apart
28	    /// from "the plan is broken". Deliberately NOT added to the shared <see cref="ExitCodes"/>
29	    /// class: it shares the numeric value of <see cref="ExitCodes.TaskFailed"/> (2) by design
30	    /// (both are the §7 "actionable condition found" code) but is a graph-specific meaning, so
31	    /// it lives here next to its only caller rather than aliasing the run-time constant.
32	    /// </summary>
33	    private const int StaleExitCode = 2;
34	
35	    public static Command Create(IConsoleIo io)
36	    {
37	        var folderArgument = FolderArgument.Create();
38	
39	        var checkOption = new Option<bool>("--check")
40	        {
41	            Description = "Report whether diagram.md (and diagram.html if present) are up to date (exit 0 fresh, 2 stale/missing, 1 on a load/validate error); writes nothing. A missing diagram.html is not stale — only a present-but-hash-mismatched one is."
42	        };
43	
44	        var stdoutOption = new Option<bool>("--stdout")
45	        {
46	            Description = "Print the diagram to stdout instead of writing diagram.md (writes nothing to disk)."
47	        };
48	
49	        var noHtmlOption = new Option<bool>("--no-html")
50	        {
51	            Description = "Write only diagram.md; skip the interactive diagram.html navigation companion. Has no effect when combined with --stdout (which writes nothing to disk)."
52	        };
53	
54	        var formatOption = new Option<string>("--format")
55	        {
56	            Description = "Diagram format. Only 'mermaid' is supported for now.",
57	            DefaultValueFactory = _ => "mermaid"
58	        };
59	        // Reserved per SSOT §10: the parsed value is intentionally unconsumed until a second
60	        // format exists. Only the AcceptOnlyFromAmong("mermaid") rejection below is active today.
61	        formatOption.AcceptOnlyFromAmong("mermaid");
62	
63	        var command = new Command("graph", "Render a Mermaid diagram of a plan folder's task/guardrail DAG.");
64	        command.Add(folderArgument);
65	        command.Add(checkOption);
66	        command.Add(stdoutOption);
67	        command.Add(formatOption);
68	        command.Add(noHtmlOption);
69	
70	        command.SetAction(parseResult =>
71	        {
72	            string folder = FolderArgument.ResolveAndAnnounce(parseResult.GetValue(folderArgument), io.Out);
73	            bool check = parseResult.GetValue(checkOption);
74	            bool toStdout = parseResult.GetValue(stdoutOption);
75	            bool noHtml = parseResult.GetValue(noHtmlOption);
76	            return Execute(folder, check, toStdout, noHtml, io);
77	        });
78	
79	        return command;
80	    }
81	
82	    private static int Execute(string folder, bool check, bool toStdout, bool noHtml, IConsoleIo io)
83	    {
84	        TextWriter output = io.Out;
85	
86	        PlanProbe.Result probe = PlanProbe.LoadAndValidate(folder);
87	        if (probe.HasErrors || probe.Plan is null)
88	        {
89	            PlanProbe.PrintDiagnostics(probe.Diagnostics, output);
90	            return ExitCodes.HarnessError;
91	        }
92	
93	        PlanDefinition plan = probe.Plan;
94	        string sourceHash = GraphSourceHash.Compute(plan);
95	        string diagramPath = Path.Combine(plan.PlanDirectory, DiagramFileName);
96	        string diagramHtmlPath = Path.Combine(plan.PlanDirectory, DiagramHtmlFileName);
97	
98	        if (check)
99	        {
100	            return Check(diagramPath, diagramHtmlPath, sourceHash, output);
101	        }
102	
103	        string diagram = MermaidRenderer.Render(plan);
104	
105	        if (toStdout)
106	        {
107	            output.WriteLine(diagram);
108	            return ExitCodes.Success;
109	        }
110	
111	        string document = ComposeDocument(diagram, sourceHash);
112	        AtomicFile.WriteAllText(diagramPath, document);
113	        output.WriteLine($"Wrote {diagramPath}");
114	
115	        // The interactive local-navigation companion (issue #33). diagram.md stays the GitHub
116	        // render; diagram.html is the pan/zoom/fullscreen viewer whose nodes click through to
117	        // their source under the plan folder. Both carry the same source-sha256 and are excluded
118	        // from guardrails.baseline, so neither causes drift. The HTML embeds the interactive
119	        // source (clean diagram + click directives); diagram.md stays click-free.
120	        if (!noHtml)
121	        {
122	            string interactive = MermaidRenderer.RenderInteractive(plan);
123	            IReadOnlyDictionary<string, string> taskFolderTargets = MermaidRenderer.TaskFolderTargets(plan);
124	            AtomicFile.WriteAllText(diagramHtmlPath, HtmlDiagramRenderer.Render(interactive, sourceHash, taskFolderTargets));
125	            output.WriteLine($"Wrote {diagramHtmlPath}");
126	        }
127	
128	        return ExitCodes.Success;
129	    }
130	
131	    /// <summary>
132	    /// <c>--check</c>: recompute the source hash and compare it to the one embedded in an
133	    /// existing <c>diagram.md</c> provenance comment. Fresh (present and equal) → exit 0;
134	    /// stale or missing → one actionable line on stdout and exit <see cref="StaleExitCode"/>
135	    /// (2) — the "regenerate" signal (SSOT §7/§10). A genuine load/validate failure never
136	    /// reaches here — <see cref="Execute"/> returns <see cref="ExitCodes.HarnessError"/> (1)
137	    /// before <c>--check</c> is dispatched — so CI can distinguish "regenerate the diagram"
138	    /// (2) from "the plan is broken" (1).
139	    /// </summary>
140	    private static int Check(string diagramPath, string diagramHtmlPath, string sourceHash, TextWriter output)
141	    {
142	        string regenHint = $"run: guardrails graph {QuoteIfNeeded(Path.GetDirectoryName(diagramPath)!)}";
143	
144	        if (!File.Exists(diagramPath))
145	        {
146	            output.WriteLine($"{DiagramFileName} missing — {regenHint}");
147	            return StaleExitCode;
148	        }
149	
150	        if (!string.Equals(ReadEmbeddedHash(File.ReadAllText(diagramPath)), sourceHash, StringComparison.Ordinal))
151	        {
152	            output.WriteLine($"{DiagramFileName} is stale — {regenHint}");
153	            return StaleExitCode;
154	        }
155	
156	        // diagram.html is optional (it is skipped by --no-html), so a MISSING one is not staleness.
157	        // But a PRESENT one carrying a different source-sha256 has drifted from diagram.md/the plan
158	        // and must regenerate — it shares the same staleness key (issue #33).
159	        if (File.Exists(diagramHtmlPath) &&
160	            !string.Equals(ReadEmbeddedHash(File.ReadAllText(diagramHtmlPath)), sourceHash, StringComparison.Ordinal))
161	        {
162	            output.WriteLine($"{DiagramHtmlFileName} is stale — {regenHint}");
163	            return StaleExitCode;
164	        }
165	
166	        return ExitCodes.Success;
167	    }
168	
169	    /// <summary>
170	    /// One-line italic caption written AFTER the closing mermaid fence (SSOT §10). It lives in
171	    /// the markdown wrapper ONLY — never inside the fenced block, the <see cref="MermaidRenderer"/>
172	    /// output, or the hashed semantic content — so it does NOT affect <c>source-sha256</c>, the
173	    /// golden render test, or <c>--stdout</c>, and two regens stay byte-identical. Its job is to
174	    /// tell a reader the diagram is structure-only: retry, feedback, and needs-human edges are
175	    /// out of scope for v1 (SSOT §10) and the static flowchart would otherwise read like a
176	    /// one-pass pipeline.
177	    /// </summary>
178	    private const string DiagramCaption =
179	        "_Structure only — retry, feedback, and needs-human edges are omitted._";
180	
181	    /// <summary>
182	    /// Compose the persisted artifact: a single-line provenance comment (SSOT §10), a fenced
183	    /// <c>mermaid</c> block holding the rendered diagram, a one-line italic caption after the
184	    /// fence (<see cref="DiagramCaption"/>), and the shared <see cref="MermaidRenderer.LegendMarkdown"/>
185	    /// block. GitHub's Mermaid sandbox has no overlay-content option, so the legend cannot live
186	    /// inside the fenced block (a Mermaid-native legend subgraph was prototyped and rendered
