1	using Guardrails.Cli.Ui;
2	using Guardrails.Core.Execution;
3	using Guardrails.Core.Journal;
4	using Guardrails.Core.Model;
5	
6	namespace Guardrails.Integration.Tests;
7	
8	/// <summary>
9	/// Exercises the on-the-fly static-site decorator (<see cref="OnTheFlyLogSiteObserver"/>, issue #141
10	/// item 2): as tasks settle it rewrites <c>logs/&lt;runId&gt;/index.html</c> with the right per-task link
11	/// kind (running → live URL, settled-with-attempts → static page, pending → plain text) and a
12	/// meta-refresh, writes each finished task's static page, and forwards EVERY event to the inner
13	/// observer. Driven directly against the decorator with hand-written attempt logs (no agent), so the
14	/// projection logic is asserted deterministically over the rendered HTML — JS is never executed.
15	/// </summary>
16	public sealed class OnTheFlyLogSiteTests
17	{
18	    [Fact]
19	    public void DuringRun_Index_ReflectsPendingRunningDone_WithLinkKinds_AndRefresh()
20	    {
21	        using var temp = new TempSite();
22	        TaskNode a = temp.Task("01-alpha");
23	        TaskNode b = temp.Task("02-beta");
24	        var liveUrls = new Dictionary<string, string> { ["01-alpha"] = "http://127.0.0.1:5000/tasks/01-alpha" };
25	
26	        var observer = new OnTheFlyLogSiteObserver(
27	            IRunObserver.Null, temp.LogsRoot, TempSite.RunId, [a, b],
28	            liveUrlForTask: id => liveUrls.TryGetValue(id, out string? u) ? u : null);
29	
30	        // Initial: both pending → both plain text, with a meta-refresh.
31	        observer.WriteInitialIndex();
32	        string index0 = temp.ReadIndex();
33	        Assert.Contains("http-equiv=\"refresh\"", index0);   // during-run page refreshes itself
34	        Assert.DoesNotContain("tasks/01-alpha", index0);     // pending → no live link yet
35	        Assert.DoesNotContain("01-alpha/index.html", index0); // pending → no static link yet
36	
37	        // 01-alpha starts: it has an attempt dir AND a live URL → it links to the LIVE server.
38	        temp.WriteAttempt("01-alpha", 1, "action-stdout.log", "running output");
39	        observer.TaskStarting(a);
40	        string index1 = temp.ReadIndex();
41	        Assert.Contains("http://127.0.0.1:5000/tasks/01-alpha", index1); // running → live URL
42	        Assert.Contains("data-status=\"running\"", index1);
43	
44	        // 01-alpha finishes succeeded → it now links to its STATIC page; its page exists on disk.
45	        observer.TaskFinished(Result("01-alpha", TaskOutcome.Succeeded));
46	        string index2 = temp.ReadIndex();
47	        Assert.Contains("01-alpha/index.html", index2);      // settled → static page link
48	        Assert.DoesNotContain("http://127.0.0.1:5000/tasks/01-alpha", index2); // no longer live
49	        Assert.Contains("data-status=\"succeeded\"", index2);
50	        Assert.True(File.Exists(Path.Combine(temp.LogsRoot, "01-alpha", "index.html")),
51	            "the finished task's static page must be written on finish (#141 items 1 & 2)");
52	
53	        // 02-beta never started → still pending plain text (no link of either kind).
54	        Assert.DoesNotContain("02-beta/index.html", index2);
55	    }
56	
57	    [Fact]
58	    public void DurableFinalSite_HasNoRefresh_AndAllStaticLinks()
59	    {
60	        using var temp = new TempSite();
61	        TaskNode a = temp.Task("01-alpha");
62	        temp.WriteAttempt("01-alpha", 1, "action-stdout.log", "done");
63	
64	        // The durable final/--export index is produced by ExportSite (the run-end path calls it): no
65	        // meta-refresh, all-static links.
66	        var journal = new JournalDocument
67	        {
68	            RunId = TempSite.RunId,
69	            PlanHash = "sha256:deadbeef",
70	            Tasks = new Dictionary<string, TaskJournalEntry>
71	            {
72	                ["01-alpha"] = new() { Status = Core.Journal.TaskStatus.Succeeded },
73	            },
74	        };
75	
76	        LogSiteRenderer.ExportSite(temp.LogsRoot, [a], journal);
77	
78	        string index = temp.ReadIndex();
79	        Assert.DoesNotContain("http-equiv=\"refresh\"", index); // durable artifact does not flicker
80	        Assert.Contains("01-alpha/index.html", index);          // settled task is a static link
81	    }
82	
83	    [Fact]
84	    public void Decorator_ForwardsEveryEvent_ToTheInnerObserver()
85	    {
86	        using var temp = new TempSite();
87	        TaskNode a = temp.Task("01-alpha");
88	        var inner = new RecordingObserver();
89	
90	        var observer = new OnTheFlyLogSiteObserver(inner, temp.LogsRoot, TempSite.RunId, [a], liveUrlForTask: null);
91	
92	        observer.TaskStarting(a);
93	        observer.GuardrailFinished(a, new GuardrailResult { Name = "01-x", Passed = true });
94	        observer.TaskFinished(Result("01-alpha", TaskOutcome.Succeeded));
95	
96	        Assert.Equal(new[] { "TaskStarting:01-alpha", "GuardrailFinished:01-alpha", "TaskFinished:01-alpha" },
97	            inner.Events);
98	    }
99	
100	    private static TaskResult Result(string id, TaskOutcome outcome) =>
101	        new() { TaskId = id, Outcome = outcome, Summary = $"{id} {outcome}" };
102	
103	    /// <summary>Records the order/identity of every forwarded event so the decorator's pass-through is provable.</summary>
104	    private sealed class RecordingObserver : IRunObserver
105	    {
106	        public List<string> Events { get; } = [];
107	
108	        public void TaskStarting(TaskNode task) => Events.Add($"TaskStarting:{task.Id}");
109	        public void TaskFinished(TaskResult result) => Events.Add($"TaskFinished:{result.TaskId}");
110	        public void GuardrailFinished(TaskNode task, GuardrailResult result) => Events.Add($"GuardrailFinished:{task.Id}");
111	    }
112	
113	    /// <summary>A throwaway logs/&lt;runId&gt;/ tree with helpers to write attempts and read the index.</summary>
114	    private sealed class TempSite : IDisposable
115	    {
116	        public const string RunId = "test-run";
117	
118	        public string Dir { get; } = Path.Combine(Path.GetTempPath(), "gr-otf-" + Guid.NewGuid().ToString("N"));
119	
120	        public string LogsRoot => Path.Combine(Dir, "logs", RunId);
121	
122	        public TempSite() => Directory.CreateDirectory(LogsRoot);
123	
124	        public TaskNode Task(string id) => new()
125	        {
126	            Id = id,
127	            Directory = Path.Combine(Dir, "tasks", id),
128	            Description = "task " + id,
